export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type Classification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

interface Rejection {
  provider: Provider;
  reason: RefusalReason;
}

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Rejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Rejection[];
}

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

interface SimpleErrorBody {
  code: "invalid_command" | "not_found";
}

interface DispatchAbortedBody {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: Classification;
  rejections: Rejection[];
}

export interface ServiceResponse {
  status: number;
  body: PublicShipment | SimpleErrorBody | DispatchAbortedBody;
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierFailure =
  | { kind: "refusal"; rejection: Rejection }
  | { kind: "rate_limited"; retryAtMs: number }
  | { kind: "abort"; classification: "unknown_failure" | "invalid_provider_response" };

type AttemptResult =
  | { kind: "confirmed"; bookingId: string }
  | CarrierFailure;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isNonblankString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function isSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value);
}

function isPositiveSafeInteger(value: unknown): value is number {
  return isSafeInteger(value) && value > 0;
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function parseRejection(value: unknown): Rejection | undefined {
  if (!isObject(value) || !isProvider(value.provider) || !isRefusalReason(value.reason)) {
    return undefined;
  }
  return { provider: value.provider, reason: value.reason };
}

function parseRejections(value: unknown): Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const rejections: Rejection[] = [];
  for (const item of value) {
    const rejection = parseRejection(item);
    if (!rejection) {
      return undefined;
    }
    rejections.push(rejection);
  }
  return rejections;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || !isNonemptyString(value.shipmentId)) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    !isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    !isNonblankString(value.recipient.name) ||
    !isNonblankString(value.recipient.postalAddress)
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    !isNonemptyString(value.id) ||
    !isNonemptyString(value.routeCode) ||
    !isPositiveSafeInteger(value.parcelGrams)
  ) {
    return undefined;
  }

  const base: ShipmentFields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  };

  if (value.state === "queued") {
    return { ...base, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...base,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    isSafeInteger(value.retryAtMs) &&
    value.retryAtMs >= 0
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections) {
      return {
        ...base,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections) {
      return { ...base, state: "unavailable", rejections };
    }
  }
  return undefined;
}

function publicRejections(rejections: readonly Rejection[]): Rejection[] {
  return rejections.map((rejection) => ({
    provider: rejection.provider,
    reason: rejection.reason,
  }));
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  if (shipment.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (shipment.state === "dispatched") {
    return {
      ...fields,
      state: "dispatched",
      provider: shipment.provider,
      bookingId: shipment.bookingId,
      dispatchedAtMs: shipment.dispatchedAtMs,
    };
  }
  if (shipment.state === "deferred") {
    return {
      ...fields,
      state: "deferred",
      nextProvider: shipment.nextProvider,
      retryAtMs: shipment.retryAtMs,
      rejections: publicRejections(shipment.rejections),
    };
  }
  return {
    ...fields,
    state: "unavailable",
    rejections: publicRejections(shipment.rejections),
  };
}

function providerRequest(shipment: ShipmentFields, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function abortResponse(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: Classification,
  rejections: readonly Rejection[],
): ServiceResponse {
  return {
    status: 500,
    body: {
      code: "dispatch_aborted",
      shipmentId,
      failedAt,
      classification,
      rejections: publicRejections(rejections),
    },
  };
}

function logAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: Classification,
  rejections: readonly Rejection[],
): void {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections: publicRejections(rejections),
  });
}

function classifyAtlasRejection(value: unknown, nowMs: number): CarrierFailure {
  if (!isObject(value)) {
    return { kind: "abort", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    if (!isRefusalReason(value.reason)) {
      return { kind: "abort", classification: "invalid_provider_response" };
    }
    return {
      kind: "refusal",
      rejection: { provider: "atlas", reason: value.reason },
    };
  }
  if (value.code === "rate_limited") {
    if (!isSafeInteger(value.retryAtMs) || value.retryAtMs <= nowMs) {
      return { kind: "abort", classification: "invalid_provider_response" };
    }
    return { kind: "rate_limited", retryAtMs: value.retryAtMs };
  }
  return { kind: "abort", classification: "unknown_failure" };
}

function classifyBeaconRejection(value: unknown, nowMs: number): CarrierFailure {
  if (!isObject(value)) {
    return { kind: "abort", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    if (!isObject(value.details) || !isRefusalReason(value.details.reason)) {
      return { kind: "abort", classification: "invalid_provider_response" };
    }
    return {
      kind: "refusal",
      rejection: { provider: "beacon", reason: value.details.reason },
    };
  }
  if (value.type === "throttled") {
    if (
      !isObject(value.details) ||
      !isSafeInteger(value.details.retryAtMs) ||
      value.details.retryAtMs <= nowMs
    ) {
      return { kind: "abort", classification: "invalid_provider_response" };
    }
    return { kind: "rate_limited", retryAtMs: value.details.retryAtMs };
  }
  return { kind: "abort", classification: "unknown_failure" };
}

function parseConfirmation(provider: Provider, value: unknown): AttemptResult {
  if (!isObject(value)) {
    return { kind: "abort", classification: "invalid_provider_response" };
  }
  if (provider === "atlas" && isNonemptyString(value.bookingId)) {
    return { kind: "confirmed", bookingId: value.bookingId };
  }
  if (provider === "beacon" && isNonemptyString(value.reference)) {
    return { kind: "confirmed", bookingId: value.reference };
  }
  return { kind: "abort", classification: "invalid_provider_response" };
}

async function attemptProvider(
  dependencies: ShippingDependencies,
  provider: Provider,
  shipment: ShipmentFields,
  command: Extract<Command, { op: "dispatch" }>,
): Promise<AttemptResult> {
  try {
    const request = providerRequest(shipment, command.recipient);
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return parseConfirmation(provider, confirmation);
  } catch (error) {
    return provider === "atlas"
      ? classifyAtlasRejection(error, command.nowMs)
      : classifyBeaconRejection(error, command.nowMs);
  }
}

function hasRefusal(rejections: readonly Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  decision: StoredShipment,
  status: 200 | 202 | 422,
  event: Record<string, unknown>,
  rejectionsForSaveFailure: readonly Rejection[],
): Promise<ServiceResponse> {
  try {
    await dependencies.repository.save(shipment.id, decision);
  } catch {
    logAbort(
      dependencies,
      shipment.id,
      "repository",
      "repository_failure",
      rejectionsForSaveFailure,
    );
    return abortResponse(
      shipment.id,
      "repository",
      "repository_failure",
      rejectionsForSaveFailure,
    );
  }
  dependencies.logger.info(event);
  return { status, body: publicShipment(decision) };
}

async function handleConfirmed(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
  provider: Provider,
  bookingId: string,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  const dispatched: DispatchedShipment = {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "dispatched",
    provider,
    bookingId,
    dispatchedAtMs: command.nowMs,
  };
  return saveDecision(
    dependencies,
    shipment,
    dispatched,
    200,
    {
      shipmentId: shipment.id,
      action: "dispatched",
      provider,
    },
    rejections,
  );
}

async function handleRateLimit(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  provider: Provider,
  retryAtMs: number,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  const deferred: DeferredShipment = {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "deferred",
    nextProvider: provider,
    retryAtMs,
    rejections: publicRejections(rejections),
  };
  return saveDecision(
    dependencies,
    shipment,
    deferred,
    202,
    {
      shipmentId: shipment.id,
      action: "deferred",
      provider,
      retryAtMs,
      rejections: publicRejections(rejections),
    },
    rejections,
  );
}

async function handleUnavailable(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  const unavailable: UnavailableShipment = {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    state: "unavailable",
    rejections: publicRejections(rejections),
  };
  return saveDecision(
    dependencies,
    shipment,
    unavailable,
    422,
    {
      shipmentId: shipment.id,
      action: "unavailable",
      rejections: publicRejections(rejections),
    },
    rejections,
  );
}

async function continueDispatch(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
  provider: Provider,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  if (hasRefusal(rejections, provider)) {
    return handleUnavailable(dependencies, shipment, rejections);
  }

  const result = await attemptProvider(dependencies, provider, shipment, command);
  if (result.kind === "confirmed") {
    return handleConfirmed(
      dependencies,
      shipment,
      command,
      provider,
      result.bookingId,
      rejections,
    );
  }
  if (result.kind === "rate_limited") {
    return handleRateLimit(
      dependencies,
      shipment,
      provider,
      result.retryAtMs,
      rejections,
    );
  }
  if (result.kind === "abort") {
    logAbort(dependencies, shipment.id, provider, result.classification, rejections);
    return abortResponse(shipment.id, provider, result.classification, rejections);
  }

  const nextRejections = [...rejections, result.rejection];
  if (provider === "atlas" && !hasRefusal(nextRejections, "beacon")) {
    return continueDispatch(dependencies, shipment, command, "beacon", nextRejections);
  }
  return handleUnavailable(dependencies, shipment, nextRejections);
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      logAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
      return abortResponse(
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (!shipment) {
      logAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
      return abortResponse(
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred") {
      if (command.nowMs < shipment.retryAtMs) {
        return { status: 202, body: publicShipment(shipment) };
      }
      return continueDispatch(
        dependencies,
        shipment,
        command,
        shipment.nextProvider,
        shipment.rejections,
      );
    }

    return continueDispatch(dependencies, shipment, command, "atlas", []);
  }

  return { handle };
}
